using AppCondominio.Modules.Procurement.Infrastructure;using Microsoft.Extensions.Diagnostics.HealthChecks;namespace AppCondominio.Api.Health;public sealed class ProcurementDatabaseHealthCheck(ProcurementDbContext dbContext):IHealthCheck{public async Task<HealthCheckResult> CheckHealthAsync(HealthCheckContext context,CancellationToken cancellationToken=default){try{return await dbContext.Database.CanConnectAsync(cancellationToken)?HealthCheckResult.Healthy("Procurement SQL Server is reachable."):HealthCheckResult.Unhealthy("Procurement SQL Server is not reachable.");}catch(Exception ex){return HealthCheckResult.Unhealthy("Procurement SQL Server readiness check failed.",ex);}}}
